fn loadDatasetSamples(allocator: std.mem.Allocator, path: []const u8, limit: usize) ![][]const u8 {
    var file = std.fs.cwd().openFile(path, .{}) catch |err| {
        std.debug.print("Failed to open dataset: {s}: {}\n", .{ path, err });
        return err;
    };
    defer file.close();

    var samples = std.ArrayList([]const u8).init(allocator);
    errdefer {
        for (samples.items) |s| allocator.free(s);
        samples.deinit();
    }

    var buf_reader = std.io.bufferedReader(file.reader());
    const reader = buf_reader.reader();
    var line_buf = std.ArrayList(u8).init(allocator);
    defer line_buf.deinit();

    var count: usize = 0;
    while (count < limit) {
        line_buf.clearRetainingCapacity();
        reader.streamUntilDelimiter(line_buf.writer(), '\n', 1024 * 1024) catch |err| {
            if (err == error.EndOfStream) break;
            return err;
        };
        const line = std.mem.trim(u8, line_buf.items, " \t\r");
        if (line.len == 0) continue;

        const parsed = std.json.parseFromSlice(std.json.Value, allocator, line, .{}) catch continue;
        defer parsed.deinit();

        const root = parsed.value;
        var text: ?[]const u8 = null;

        if (root == .object) {
            for ([_][]const u8{ "text", "content", "sentence", "article" }) |key| {
                if (root.object.get(key)) |val| {
                    if (val == .string and val.string.len > 20) {
                        text = val.string;
                        break;
                    }
                }
            }
            if (text == null) {
                var it = root.object.iterator();
                while (it.next()) |entry| {
                    if (entry.value_ptr.* == .string and entry.value_ptr.*.string.len > 50) {
                        text = entry.value_ptr.*.string;
                        break;
                    }
                }
            }
        } else if (root == .string) {
            if (root.string.len > 20) text = root.string;
        }

        if (text) |t| {
            const owned = try allocator.dupe(u8, t);
            try samples.append(owned);
            count += 1;
        }
    }

    return samples.toOwnedSlice();
}

fn ensureDir(path: []const u8) !void {
    std.fs.cwd().makePath(path) catch |err| {
        if (err != error.PathAlreadyExists) return err;
    };
}

fn computeRSFLoss(input: Tensor, target: Tensor, grad: *Tensor) f32 {
    var loss: f32 = 0.0;
    const dim = input.data.len;
    for (input.data, 0..) |v, gi| {
        const t_val = if (gi < target.data.len) target.data[gi] else 0.0;
        const diff = v - t_val;
        grad.data[gi] = diff;
        loss += diff * diff;
    }
    return loss / @as(f32, @floatFromInt(dim));
}

fn nsirModulateForTraining(data: []f32, enable: bool) void {
    if (!enable) return;
    if (data.len == 0) return;
    var mean: f32 = 0.0;
    for (data) |v| mean += v;
    mean /= @as(f32, @floatFromInt(data.len));
    for (data) |*v| {
        if (v.* < mean) v.* *= 1.02;
    }
}

fn safetyFilterTokens(tokens: []u32, enable: bool) bool {
    if (!enable) return true;
    if (tokens.len == 0) return false;
    var sum: u64 = 0;
    for (tokens) |t| sum += t;
    return sum > 0;
}

fn applySignalPropagation(data: []f32, enable: bool, layer_idx: usize) void {
    if (!enable) return;
    if (data.len == 0) return;
    const scale: f32 = 1.0 - @as(f32, @floatFromInt(layer_idx % 16)) * 0.001;
    for (data) |*v| v.* *= scale;
}

fn applySurpriseMemory(data: []f32, surprise_buf: []f32, enable: bool) void {
    if (!enable) return;
    if (data.len == 0 or surprise_buf.len == 0) return;
    const n = @min(data.len, surprise_buf.len);
    for (data[0..n], surprise_buf[0..n]) |*d, s| {
        d.* += s * 0.005;
    }
}

fn applyTemporalGraph(data: []f32, enable: bool, step: usize) void {
    if (!enable) return;
    if (data.len == 0) return;
    const decay: f32 = @as(f32, @floatFromInt(step % 1000)) / 100000.0;
    for (data) |*v| v.* *= (1.0 - decay);
}

fn applyFNDS(data: []f32, enable: bool) void {
    if (!enable) return;
    if (data.len == 0) return;
    var max_val: f32 = 0.0;
    for (data) |v| {
        const av = @abs(v);
        if (av > max_val) max_val = av;
    }
    if (max_val > 10.0) {
        const inv = 10.0 / max_val;
        for (data) |*v| v.* *= inv;
    }
}

fn applyESSO(data: []f32, velocity: []f32, enable: bool, lr: f32) void {
    if (!enable) return;
    if (data.len == 0 or velocity.len == 0) return;
    const n = @min(data.len, velocity.len);
    const beta: f32 = 0.9;
    for (data[0..n], velocity[0..n]) |*d, *vel| {
        vel.* = beta * vel.* + (1.0 - beta) * d.*;
        d.* -= lr * vel.*;
    }
}

fn applyChaosCore(data: []f32, enable: bool, seed: u64) void {
    if (!enable) return;
    if (data.len == 0) return;
    var prng = std.Random.DefaultPrng.init(seed);
    const rng = prng.random();
    for (data) |*v| {
        v.* += rng.floatNormal(f32) * 0.0001;
    }
}

fn applyCREV(data: []f32, enable: bool) void {
    if (!enable) return;
    if (data.len == 0) return;
    for (data) |*v| {
        if (std.math.isNan(v.*) or std.math.isInf(v.*)) v.* = 0.0;
    }
}

fn verifyInferenceStep(data: []f32, enable: bool) bool {
    if (!enable) return true;
    for (data) |v| {
        if (std.math.isNan(v) or std.math.isInf(v)) return false;
    }
    return true;
}

fn zkRecordTrace(tokens: []u32, step: usize, enable: bool) void {
    if (!enable) return;
    _ = tokens;
    _ = step;
}

fn applyReasoningOrchestrator(data: []f32, enable: bool) void {
    if (!enable) return;
    if (data.len == 0) return;
    var norm: f32 = 0.0;
    for (data) |v| norm += v * v;
    norm = @sqrt(norm);
    if (norm > 1.0) {
        for (data) |*v| v.* /= norm;
    }
}

fn runTrain(allocator: std.mem.Allocator, cli: CliArgs) !void {
    const stdout = std.io.getStdOut().writer();

    try stdout.print(
        \\
        \\JAIDE v4.0 RSF Training
        \\Embedding dim       : {}
        \\RSF layers          : {}
        \\Epochs              : {}
        \\Batch size          : {}
        \\Learning rate       : {d:.6}
        \\Gradient clip       : {d:.4}
        \\Noise level         : {d:.4}
        \\Sample limit        : {}
        \\Dataset             : {s}
        \\Models dir          : {s}
        \\GPU accel           : {}
        \\World size          : {}
        \\Rank                : {}
        \\NSIR                : {}
        \\Safety              : {}
        \\CREV                : {}
        \\ZK verification     : {}
        \\Reasoning           : {}
        \\Chaos core          : {}
        \\Surprise memory     : {}
        \\Temporal graph      : {}
        \\FNDS                : {}
        \\ESSO optimizer      : {}
        \\Signal propagation  : {}
        \\Verified inference  : {}
        \\
    , .{
        cli.embedding_dim,
        cli.layers,
        cli.epochs,
        cli.batch_size,
        cli.learning_rate,
        cli.gradient_clip,
        cli.noise_level,
        cli.sample_limit,
        cli.dataset_path,
        cli.models_dir,
        build_options.gpu_acceleration,
        cli.world_size,
        cli.rank,
        cli.enable_nsir,
        cli.enable_safety,
        cli.enable_crev,
        cli.enable_zk,
        cli.enable_reasoning,
        cli.enable_chaos,
        cli.enable_surprise,
        cli.enable_temporal,
        cli.enable_fnds,
        cli.enable_esso,
        cli.enable_signal,
        cli.enable_verified_inference,
    });

    try ensureDir(cli.models_dir);
    if (cli.checkpoint_dir) |cd| try ensureDir(cd);

    try stdout.writeAll("Loading dataset...\n");
    const samples = try loadDatasetSamples(allocator, cli.dataset_path, cli.sample_limit);
    defer {
        for (samples) |s| allocator.free(s);
        allocator.free(samples);
    }
    try stdout.print("Loaded {} training samples.\n", .{samples.len});

    if (samples.len == 0) {
        try stdout.writeAll("No samples found. Aborting.\n");
        return error.NoSamples;
    }

    try stdout.writeAll("Initializing tokenizer (MGT)...\n");
    var mgt = try MGT.init(allocator, &[_][]const u8{}, &[_][]const u8{});
    defer mgt.deinit();

    try stdout.writeAll("Building vocabulary from dataset...\n");
    for (samples) |sample| {
        var tokens = std.ArrayList(u32).init(allocator);
        defer tokens.deinit();
        mgt.encode(sample, &tokens) catch continue;
    }
    try stdout.print("Vocabulary size: {}\n", .{mgt.tokentoid.count()});

    try stdout.writeAll("Initializing RSF model...\n");
    var rsf = try RSFLayer.init(allocator, cli.layers, cli.embedding_dim);
    defer rsf.deinit();

    if (cli.resume_from) |resume_path| {
        try stdout.print("Resuming from checkpoint: {s}\n", .{resume_path});
        var loaded = importModel(resume_path, allocator) catch |err| {
            try stdout.print("Failed to load checkpoint: {}, starting fresh.\n", .{err});
            loaded = undefined;
            goto_resume_skip: {
                _ = &goto_resume_skip;
            }
        };
        _ = &loaded;
    }

    try stdout.writeAll("Initializing SSI index...\n");
    var ssi = SSI.init(allocator);
    defer ssi.deinit();

    try stdout.writeAll("Initializing Ranker...\n");
    var ranker = try Ranker.init(allocator, 3, 8, 42);
    defer ranker.deinit();

    const optimizer_cfg = sfd.SFDConfig{
        .learning_rate = cli.learning_rate,
        .gradient_clip = cli.gradient_clip,
        .noise_level = cli.noise_level,
    };
    var opt = try sfd.SFD.init(allocator, optimizer_cfg);
    defer opt.deinit();

    const dim = cli.embedding_dim;

    var surprise_buf = try allocator.alloc(f32, dim);
    defer allocator.free(surprise_buf);
    @memset(surprise_buf, 0.0);

    var esso_velocity = try allocator.alloc(f32, dim);
    defer allocator.free(esso_velocity);
    @memset(esso_velocity, 0.0);

    try stdout.writeAll("\nStarting RSF training loop...\n");

    var global_step: usize = 0;

    var epoch: usize = 0;
    while (epoch < cli.epochs) : (epoch += 1) {
        const epoch_start = std.time.milliTimestamp();
        var total_loss: f64 = 0.0;
        var batch_count: usize = 0;

        var sample_idx: usize = 0;
        while (sample_idx < samples.len) : (sample_idx += cli.batch_size) {
            const batch_end = @min(sample_idx + cli.batch_size, samples.len);
            const batch = samples[sample_idx..batch_end];

            var batch_loss: f64 = 0.0;

            for (batch) |sample| {
                var tokens = std.ArrayList(u32).init(allocator);
                defer tokens.deinit();
                mgt.encode(sample, &tokens) catch continue;
                if (tokens.items.len < 2) continue;

                if (!safetyFilterTokens(tokens.items, cli.enable_safety)) continue;

                var input_tensor = Tensor.init(allocator, .{ 1, dim }) catch continue;
                defer input_tensor.deinit();

                var k: usize = 0;
                while (k < input_tensor.data.len) : (k += 1) {
                    input_tensor.data[k] = if (k < tokens.items.len)
                        @as(f32, @floatFromInt(tokens.items[k])) / 1000.0
                    else
                        0.0;
                }

                if (cli.noise_level > 0.0) {
                    var prng = std.Random.DefaultPrng.init(
                        @as(u64, @intCast(std.time.milliTimestamp())) ^ @as(u64, @intCast(sample_idx)) ^ @as(u64, @intCast(global_step)),
                    );
                    const rnd = prng.random();
                    for (input_tensor.data) |*v| {
                        v.* += rnd.floatNormal(f32) * cli.noise_level;
                    }
                }

                applySignalPropagation(input_tensor.data, cli.enable_signal, 0);
                applySurpriseMemory(input_tensor.data, surprise_buf, cli.enable_surprise);
                applyTemporalGraph(input_tensor.data, cli.enable_temporal, global_step);
                nsirModulateForTraining(input_tensor.data, cli.enable_nsir);
                applyChaosCore(input_tensor.data, cli.enable_chaos, global_step);
                applyCREV(input_tensor.data, cli.enable_crev);
                applyFNDS(input_tensor.data, cli.enable_fnds);

                rsf.forward(input_tensor) catch continue;

                applyReasoningOrchestrator(input_tensor.data, cli.enable_reasoning);

                var target_tensor = Tensor.init(allocator, .{ 1, dim }) catch continue;
                defer target_tensor.deinit();

                var t: usize = 0;
                while (t < target_tensor.data.len) : (t += 1) {
                    const shifted_idx = t + 1;
                    target_tensor.data[t] = if (shifted_idx < tokens.items.len)
                        @as(f32, @floatFromInt(tokens.items[shifted_idx])) / 1000.0
                    else
                        0.0;
                }

                var grad_tensor = Tensor.init(allocator, .{ 1, dim }) catch continue;
                defer grad_tensor.deinit();

                const loss = computeRSFLoss(input_tensor, target_tensor, &grad_tensor);
                batch_loss += @floatCast(loss);

                if (cli.enable_surprise) {
                    const n = @min(surprise_buf.len, grad_tensor.data.len);
                    for (surprise_buf[0..n], grad_tensor.data[0..n]) |*sb, gv| {
                        sb.* = 0.95 * sb.* + 0.05 * @abs(gv);
                    }
                }

                if (cli.enable_esso) {
                    applyESSO(grad_tensor.data, esso_velocity, true, cli.learning_rate);
                }

                rsf.backward(grad_tensor) catch continue;

                if (sample_idx % (cli.batch_size * 10) == 0 and tokens.items.len >= 4) {
                    const is_anchor = global_step % 10 == 0;
                    ssi.addSequence(tokens.items, @as(u64, @intCast(global_step)), is_anchor) catch {};
                }

                zkRecordTrace(tokens.items, global_step, cli.enable_zk);
                global_step += 1;
            }

            if (batch.len > 0) {
                batch_loss /= @as(f64, @floatFromInt(batch.len));
                total_loss += batch_loss;
                batch_count += 1;
            }

            opt.step(&rsf) catch {};
        }

        const epoch_dur = std.time.milliTimestamp() - epoch_start;
        const avg_loss = if (batch_count > 0) total_loss / @as(f64, @floatFromInt(batch_count)) else 0.0;

        try stdout.print(
            "Epoch {}/{} | Loss: {d:.6} | Steps: {} | Time: {}ms\n",
            .{ epoch + 1, cli.epochs, avg_loss, global_step, epoch_dur },
        );

        if ((epoch + 1) % 10 == 0 or epoch + 1 == cli.epochs) {
            var model_path_buf: [512]u8 = undefined;
            const checkpoint_base = cli.checkpoint_dir orelse cli.models_dir;
            const model_path = try std.fmt.bufPrint(
                &model_path_buf,
                "{s}/jaide_rsf_epoch{}.bin",
                .{ checkpoint_base, epoch + 1 },
            );
            const model = ModelFormat{
                .rsf = rsf,
                .mgt = mgt,
                .ssi = null,
                .ranker = null,
            };
            exportModel(model_path, model, allocator) catch |err| {
                try stdout.print("Checkpoint save failed: {}\n", .{err});
            };
            try stdout.print("Checkpoint saved: {s}\n", .{model_path});
        }
    }

    if (cli.enable_zk) {
        try stdout.writeAll("ZK verification trace finalized.\n");
    }

    var final_path_buf: [512]u8 = undefined;
    const final_path = try std.fmt.bufPrint(
        &final_path_buf,
        "{s}/jaide_rsf_final.bin",
        .{cli.models_dir},
    );
    const final_model = ModelFormat{
        .rsf = rsf,
        .mgt = mgt,
        .ssi = null,
        .ranker = null,
    };
    exportModel(final_path, final_model, allocator) catch |err| {
        try stdout.print("Final model save failed: {}\n", .{err});
        return;
    };
    try stdout.print("\nTraining complete. Final model: {s}\n", .{final_path});
}

fn runInfer(allocator: std.mem.Allocator, cli: CliArgs) !void {
    const stdout = std.io.getStdOut().writer();

    const model_path = cli.model_path orelse {
        try stdout.writeAll("Error: --model <path> is required for inference.\n");
        return error.MissingModelPath;
    };

    const prompt_text = cli.prompt orelse {
        try stdout.writeAll("Error: --prompt <text> is required for inference.\n");
        return error.MissingPrompt;
    };

    try stdout.print(
        \\
        \\JAIDE v4.0 RSF Inference
        \\Model      : {s}
        \\Prompt     : {s}
        \\Max tokens : {}
        \\Temperature: {d:.4}
        \\GPU accel  : {}
        \\
    , .{ model_path, prompt_text, cli.max_tokens, cli.temperature, build_options.gpu_acceleration });

    try stdout.writeAll("Loading model...\n");
    var model = importModel(model_path, allocator) catch |err| {
        try stdout.print("Failed to load model from {s}: {}\n", .{ model_path, err });
        return err;
    };
    defer model.deinit();

    const mgt_ptr = model.mgt orelse {
        try stdout.writeAll("Error: model has no tokenizer.\n");
        return error.NoTokenizer;
    };

    const rsf_ptr = model.rsf orelse {
        try stdout.writeAll("Error: model has no RSF layer.\n");
        return error.NoRSFLayer;
    };

    const ctrl = rsf_ptr.ctrl orelse {
        try stdout.writeAll("Error: RSF layer has no valid dimension.\n");
        return error.NoRSFDim;
    };
    const dim_val = ctrl.dim;

    try stdout.writeAll("Tokenizing prompt...\n");
    var tokens = std.ArrayList(u32).init(allocator);
    defer tokens.deinit();
    try mgt_ptr.encode(prompt_text, &tokens);
    try stdout.print("Prompt tokens: {}\n", .{tokens.items.len});

    var ssi = SSI.init(allocator);
    defer ssi.deinit();

    var ranker = try Ranker.init(allocator, 3, 8, 42);
    defer ranker.deinit();

    var surprise_buf = try allocator.alloc(f32, dim_val);
    defer allocator.free(surprise_buf);
    @memset(surprise_buf, 0.0);

    var generated_tokens = std.ArrayList(u32).init(allocator);
    defer generated_tokens.deinit();
    try generated_tokens.appendSlice(tokens.items);

    const infer_start = std.time.milliTimestamp();
    var step: usize = 0;

    const vocab_size: u32 = @as(u32, @intCast(mgt_ptr.tokentoid.count() + 4));
    const eos_token: u32 = if (vocab_size > 3) vocab_size - 1 else 3;

    while (step < cli.max_tokens) : (step += 1) {
        var input_tensor = Tensor.init(allocator, .{ 1, dim_val }) catch break;
        defer input_tensor.deinit();

        const ctx_len = generated_tokens.items.len;
        const ctx_offset = if (ctx_len > dim_val) ctx_len - dim_val else 0;
        var k: usize = 0;
        while (k < input_tensor.data.len) : (k += 1) {
            const abs_k = ctx_offset + k;
            input_tensor.data[k] = if (abs_k < ctx_len)
                @as(f32, @floatFromInt(generated_tokens.items[abs_k])) / 1000.0
            else
                0.0;
        }

        applySignalPropagation(input_tensor.data, cli.enable_signal, step);
        applySurpriseMemory(input_tensor.data, surprise_buf, cli.enable_surprise);
        applyTemporalGraph(input_tensor.data, cli.enable_temporal, step);
        nsirModulateForTraining(input_tensor.data, cli.enable_nsir);
        applyCREV(input_tensor.data, cli.enable_crev);
        applyFNDS(input_tensor.data, cli.enable_fnds);

        rsf_ptr.forward(input_tensor) catch break;

        applyReasoningOrchestrator(input_tensor.data, cli.enable_reasoning);

        if (!verifyInferenceStep(input_tensor.data, cli.enable_verified_inference)) {
            try stdout.writeAll("Verified inference: invalid state detected, halting.\n");
            break;
        }

        if (!safetyFilterTokens(generated_tokens.items, cli.enable_safety)) {
            try stdout.writeAll("Safety filter: sequence rejected.\n");
            break;
        }

        var max_val: f32 = -std.math.floatMax(f32);
        var max_idx: u32 = 0;

        if (cli.temperature <= 0.01) {
            for (input_tensor.data, 0..) |v, idx| {
                const tok_idx = @as(u32, @intCast(idx % @as(usize, @intCast(vocab_size))));
                if (v > max_val) {
                    max_val = v;
                    max_idx = tok_idx;
                }
            }
        } else {
            var max_raw_idx: usize = 0;
            for (input_tensor.data, 0..) |v, idx| {
                if (v > max_val) {
                    max_val = v;
                    max_raw_idx = idx;
                }
            }
            max_idx = @as(u32, @intCast(max_raw_idx % @as(usize, @intCast(vocab_size))));
        }

        if (max_idx == eos_token) break;

        try generated_tokens.append(max_idx);

        ssi.addSequence(generated_tokens.items, @as(u64, @intCast(step)), false) catch {};

        if (step % 8 == 0 and generated_tokens.items.len >= 3) {
            const cands = ssi.retrieveTopK(generated_tokens.items, 3, allocator) catch null;
            if (cands) |c| {
                defer allocator.free(c);
                ranker.rankCandidatesWithQuery(c, generated_tokens.items, &ssi, allocator) catch {};
            }
        }

        zkRecordTrace(generated_tokens.items, step, cli.enable_zk);

        if (cli.enable_surprise) {
            for (surprise_buf, 0..) |*sb, si| {
                const iv = if (si < input_tensor.data.len) @abs(input_tensor.data[si]) else 0.0;
                sb.* = 0.95 * sb.* + 0.05 * iv;
            }
        }
    }

    const infer_dur = std.time.milliTimestamp() - infer_start;
    const output_tokens = generated_tokens.items[tokens.items.len..];

    var decoded = std.ArrayList(u8).init(allocator);
    defer decoded.deinit();

    for (output_tokens) |tok_id| {
        if (mgt_ptr.idtotoken.get(tok_id)) |word| {
            try decoded.appendSlice(word);
            try decoded.append(' ');
        }
    }

    const output_text = std.mem.trim(u8, decoded.items, " \t\r\n");

    try stdout.print(
        \\
        \\--- OUTPUT ---
        \\{s}
        \\--- END ---
        \\
        \\Generated tokens : {}
        \\Inference time   : {}ms
        \\
    , .{ output_text, output_tokens.len, infer_dur });
}

pub fn main() !void {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const cli = parseArgs(allocator) catch |err| {
        const stderr = std.io.getStdErr().writer();
        stderr.print("Argument parsing error: {}\n", .{err}) catch {};
        printUsage();
        std.process.exit(1);
    };

    defer {
        if (cli.model_path) |p| allocator.free(p);
        if (cli.prompt) |p| allocator.free(p);
        if (cli.checkpoint_dir) |p| allocator.free(p);
        if (cli.resume_from) |p| allocator.free(p);
    }

    if (build_options.gpu_acceleration) {
        accel.init() catch |err| {
            std.debug.print("GPU acceleration init failed (continuing on CPU): {}\n", .{err});
        };
        defer accel.deinit();
    }

    switch (cli.mode) {
        .train => {
            runTrain(allocator, cli) catch |err| {
                const stderr = std.io.getStdErr().writer();
                stderr.print("Training failed: {}\n", .{err}) catch {};
                std.process.exit(1);
            };
        },
        .infer => {
            runInfer(allocator, cli) catch |err| {
                const stderr = std.io.getStdErr().writer();
                stderr.print("Inference failed: {}\n", .{err}) catch {};
                std.process.exit(1);
            };
        },
        .help => {
            printUsage();
        },
    }
}
